begin;
set local statement_timeout='60s';
do $$
declare trainer uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); people uuid[]:=array[gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid()];
 relations uuid[]:=array[gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid()];
 exercise uuid; template uuid; revised uuid; personal uuid; series uuid; assignment uuid; unrelated uuid:=gen_random_uuid(); execution uuid; set_id uuid;
 op uuid:=gen_random_uuid(); withdraw_op uuid:=gen_random_uuid();
 monday date:=current_date-(extract(isodow from current_date)::integer-1)+14;
 recipe jsonb; recipients jsonb; all_recipients jsonb; plan jsonb; receipt jsonb; response jsonb; withdrawal jsonb; current_plan jsonb;
begin
 insert into auth.users(id,email) values(trainer,trainer||'@trainer-recurrence.invalid'),(outsider,outsider||'@trainer-recurrence.invalid');
 for i in 1..4 loop
  insert into auth.users(id,email) values(people[i],people[i]||'@trainer-recurrence.invalid');
 end loop;
 insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),trainer,'totp','verified',now(),now()),(gen_random_uuid(),outsider,'totp','verified',now(),now());
 insert into public.admin_permissions(user_id) values(outsider);
 insert into public.trainer_access(trainer_id,enabled,client_limit,last_reason) values(trainer,true,4,'Fixture serie finita');
 for i in 1..4 loop insert into public.trainer_client_relations(id,trainer_id,client_id,accepted_at) values(relations[i],trainer,people[i],now()); end loop;
 select id into exercise from public.exercises where is_public and id<>'20000000-0000-4000-8000-000000000004' order by id limit 1;
 recipe:=jsonb_build_object('name','Receta finita','blocks',jsonb_build_array(jsonb_build_object('name','Fuerza','format','straight_sets','rounds',1,'rest_after_seconds',0,
  'exercises',jsonb_build_array(jsonb_build_object('exercise_id',exercise,'sets',jsonb_build_array(jsonb_build_object('target_reps',8,'rest_after_seconds',60)))))));
 select jsonb_agg(jsonb_build_object('client_id',people[i],'relation_id',relations[i]) order by i) into recipients from generate_series(1,2) i;
 select jsonb_agg(jsonb_build_object('client_id',people[i],'relation_id',relations[i]) order by i) into all_recipients from generate_series(1,4) i;
 perform set_config('request.jwt.claim.sub',trainer::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',trainer,'role','authenticated','aal','aal2')::text,true);
 set local role authenticated;
 template:=public.save_trainer_workout(gen_random_uuid(),recipe);
 begin perform public.preview_trainer_recurrence(recipients,template,monday,0,array[1]);raise exception 'Acepta cero semanas';exception when invalid_parameter_value then null;end;
 begin perform public.preview_trainer_recurrence(recipients,template,monday,13,array[1]);raise exception 'Acepta más de doce semanas';exception when invalid_parameter_value then null;end;
 begin perform public.preview_trainer_recurrence(recipients,template,monday+1,2,array[1]);raise exception 'Semana sin lunes';exception when invalid_parameter_value then null;end;
 begin perform public.preview_trainer_recurrence(recipients,template,monday,2,array[0]);raise exception 'Día fuera de rango';exception when invalid_parameter_value then null;end;
 begin perform public.preview_trainer_recurrence(recipients,template,monday,2,array[1,1]);raise exception 'Día duplicado';exception when invalid_parameter_value then null;end;
 begin perform public.preview_trainer_recurrence(recipients,template,monday,2,'{}'::integer[]);raise exception 'Serie sin días';exception when invalid_parameter_value then null;end;
 begin perform public.preview_trainer_recurrence(all_recipients,template,monday,12,array[1,2,3,4,5,6,7]);raise exception 'Más de 256 citas';exception when invalid_parameter_value then null;end;
 plan:=public.preview_trainer_recurrence(recipients,template,monday,2,array[3,1],'Indicaciones fijas');
 if (plan->>'assignment_count')::integer<>8 or jsonb_array_length(plan->'preview'->0->'dates')<>4 or plan->'weekdays'<>'[1,3]'::jsonb then raise exception 'Fechas finitas incorrectas';end if;
 if jsonb_array_length(public.list_trainer_recurrences())<>0 then raise exception 'Preview crea serie';end if;
 perform set_config('request.jwt.claim.sub',people[1]::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',people[1],'role','authenticated','aal','aal1')::text,true);
 personal:=public.create_personal_workout_template(jsonb_set(recipe,'{name}','"Plan personal secreto"'));
 perform public.schedule_workout(personal,monday);
 perform set_config('request.jwt.claim.sub',trainer::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',trainer,'role','authenticated','aal','aal2')::text,true);
 begin perform public.create_trainer_recurrence(op,recipients,template,monday,2,array[3,1],'Indicaciones fijas',plan->>'fingerprint');raise exception 'Confirma coincidencia nueva sin revisión';exception when serialization_failure then null;end;
 if jsonb_array_length(public.list_trainer_recurrences())<>0 then raise exception 'Rechazo deja serie parcial';end if;
 plan:=public.preview_trainer_recurrence(recipients,template,monday,2,array[3,1],'Indicaciones fijas');
 if plan::text like '%Plan personal secreto%' or not exists(select 1 from jsonb_array_elements(plan->'preview') x where jsonb_array_length(x->'coincidences')>0) then raise exception 'Coincidencia revela receta personal o falta';end if;
 receipt:=public.create_trainer_recurrence(op,recipients,template,monday,2,array[3,1],'Indicaciones fijas',plan->>'fingerprint');
 series:=(receipt->>'series_id')::uuid;
 if (receipt->>'assignment_count')::integer<>8 or jsonb_array_length(receipt->'recipients')<>2 then raise exception 'Serie incompleta';end if;
 if public.create_trainer_recurrence(op,recipients,template,monday,2,array[3,1],'Indicaciones fijas',plan->>'fingerprint')<>receipt then raise exception 'Serie no idempotente';end if;
 begin perform public.create_trainer_recurrence(op,recipients,template,monday,3,array[3,1],'Indicaciones fijas',plan->>'fingerprint');raise exception 'Orden cambia duración';exception when invalid_parameter_value then null;end;
 response:=public.list_trainer_recurrences();
 if jsonb_array_length(response)<>1 or (response->0->>'pending_count')::integer<>8 then raise exception 'Listado no refleja serie';end if;
 select (x->'assignment_ids'->>0)::uuid into assignment from jsonb_array_elements(receipt->'recipients') x where x->>'client_id'=people[1]::text;
 perform public.assign_trainer_workout(unrelated,relations[1],template,monday+8,'Fuera de serie');
 revised:=public.save_trainer_workout(gen_random_uuid(),jsonb_set(recipe,'{name}','"Biblioteca nueva"'),template);
 if public.get_trainer_assignment(assignment)->>'template_id'<>template::text then raise exception 'Revisar biblioteca cambia serie';end if;
 withdrawal:=public.preview_trainer_recurrence_withdrawal(series,monday);
 if jsonb_array_length(withdrawal->'items')<>8 then raise exception 'Preview retirada no abarca serie';end if;
 perform set_config('request.jwt.claim.sub',people[1]::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',people[1],'role','authenticated','aal','aal1')::text,true);
 execution:=public.start_scheduled_workout(assignment);
 perform set_config('request.jwt.claim.sub',trainer::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',trainer,'role','authenticated','aal','aal2')::text,true);
 begin perform public.withdraw_trainer_recurrence(gen_random_uuid(),series,monday,withdrawal->>'fingerprint');raise exception 'Retira tras inicio sin revisión';exception when serialization_failure then null;end;
 if public.get_trainer_assignment(assignment)->>'status'<>'in_progress' then raise exception 'Retirada interrumpe ejecución';end if;
 withdrawal:=public.preview_trainer_recurrence_withdrawal(series,monday+7);
 response:=public.withdraw_trainer_recurrence(withdraw_op,series,monday+7,withdrawal->>'fingerprint');
 if (response->>'cancelled_count')::integer<>4 then raise exception 'Retirada no respeta fecha civil';end if;
 if public.withdraw_trainer_recurrence(withdraw_op,series,monday+7,withdrawal->>'fingerprint')<>response then raise exception 'Retirada no idempotente';end if;
 if public.get_trainer_assignment(unrelated)->>'status'<>'planned' then raise exception 'Retirada afecta cita fuera de serie';end if;
 if public.get_trainer_assignment(assignment)->>'status'<>'in_progress' then raise exception 'Retirada afecta iniciada';end if;
 if not exists(select 1 from public.trainer_client_relations where id=relations[1] and ended_at is null) then raise exception 'Retirada da de baja al alumno';end if;
 current_plan:=public.preview_trainer_recurrence_withdrawal(series,monday);
 if jsonb_array_length(current_plan->'items')<>3 or (current_plan->>'excluded_count')::integer<>5 then raise exception 'Retirada no explica excluidas';end if;
 perform set_config('request.jwt.claim.sub',people[1]::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',people[1],'role','authenticated','aal','aal1')::text,true);
 select id into set_id from public.workout_execution_sets where execution_id=execution limit 1;
 perform public.complete_workout_set(set_id,p_actual_reps=>8);
 perform public.finish_workout_execution(execution,6,'Historial conservado',null,null,'manual');
 begin perform public.list_trainer_recurrences();raise exception 'Alumno lista series profesionales';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',trainer::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',trainer,'role','authenticated','aal','aal2')::text,true);
 begin perform public.withdraw_trainer_recurrence(gen_random_uuid(),series,monday,current_plan->>'fingerprint');raise exception 'No detecta finalización concurrente';exception when serialization_failure then null;end;
 withdrawal:=public.preview_trainer_recurrence_withdrawal(series,monday);
 perform public.withdraw_trainer_recurrence(gen_random_uuid(),series,monday,withdrawal->>'fingerprint');
 if public.get_trainer_assignment(assignment)->>'status'<>'completed' or public.get_trainer_assignment_result(assignment)->>'notes'<>'Historial conservado' then raise exception 'Pierde historial completado';end if;
 if (public.list_trainer_recurrences()->0->>'pending_count')::integer<>0 then raise exception 'Quedan pendientes retirables';end if;
 if public.create_trainer_recurrence(op,recipients,template,monday,2,array[3,1],'Indicaciones fijas',plan->>'fingerprint')<>receipt then raise exception 'Cambio de estado rompe recibo original';end if;
 reset role;
 update public.trainer_access set enabled=false where trainer_id=trainer;
 set local role authenticated;
 begin perform public.preview_trainer_recurrence(recipients,revised,monday+14,2,array[1]);
  raise exception 'Acceso deshabilitado previsualiza coincidencias de recurrencia';exception when insufficient_privilege then null;end;
 if jsonb_array_length(public.list_trainer_recurrences())<>1
  or public.get_trainer_assignment_result(assignment)->>'notes'<>'Historial conservado'
  or jsonb_array_length(public.preview_trainer_recurrence_withdrawal(series,monday)->'items')<>0 then
  raise exception 'Deshabilitar acceso elimina consulta histórica de la serie propia';end if;
 reset role;
 update public.trainer_access set enabled=true where trainer_id=trainer;
 set local role authenticated;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',trainer,'role','authenticated','aal','aal1')::text,true);
 begin perform public.list_trainer_recurrences();raise exception 'Lista sin MFA';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'role','authenticated','aal','aal2')::text,true);
 if jsonb_array_length(public.list_trainer_recurrences())<>0 then raise exception 'ADMIN lee serie ajena';end if;
 begin perform public.preview_trainer_recurrence_withdrawal(series,monday);raise exception 'ADMIN previsualiza retirada ajena';exception when insufficient_privilege then null;end;
 begin perform public.withdraw_trainer_recurrence(gen_random_uuid(),series,monday,withdrawal->>'fingerprint');raise exception 'ADMIN retira serie ajena';exception when insufficient_privilege then null;end;
 begin perform 1 from trainer_private.recurrence_assignments;raise exception 'Tabla privada expuesta';exception when insufficient_privilege then null;end;
 if has_function_privilege('anon','public.list_trainer_recurrences(timestamptz,uuid)','EXECUTE') then raise exception 'Anónimo lista series';end if;
 reset role;
end $$;
select 'trainer_finite_recurrence: OK' as result;
rollback;
